    schaeferNote: 'نموذج Schaefer ليس معياراً هندسياً: يحسب التوهين الجوي وسطوع السماء وعتبة رؤية العين ويعطي المعامل R (R = ٠ يعني احتمال ٥٠٪ للرؤية). خطوة «كشف الهلال الرفيع» غير منشورة في الأبحاث وقد أُعيد بناؤها في هذا التطبيق: خطؤها مقارنةً بقيم R المنشورة لـ Schaefer نفسه على ٩٤ رصداً نحو ٠٫١٧ (عدم اليقين الرصدي ≈ ٠٫٤٣). وبدون بيانات جوية محلية يُقدَّر التوهين، وهو أكبر مصدر للخطأ.',
