    marja1Horizon: 'اتحاد الأفق شرط. إذا كان فرق الأفق بين مدينتين بمقدار بحيث لو فُرضت الرؤية في إحداهما لا تمكن الرؤية في الأخرى، لا تكفي. لكن حكم ولي الفقيه نافذ لجميع نقاط البلاد.',

