    schaeferNote: 'Schaefer\'s model is not a geometric criterion: it computes atmospheric extinction, sky brightness and the eye\'s detection threshold, and returns the parameter R (R = 0 means a 50% chance of seeing it). The thin-crescent detection step is not published in the papers and is reconstructed in this app: its error against Schaefer\'s own published R values over 94 observations is about 0.17 (observational uncertainty ≈ 0.43). Without local atmospheric data the extinction is estimated, which is the largest source of error.',
